import { useState } from 'react'
import { ArrowLeft, ArrowRight } from './Icons.jsx'

// Shows one photo at a time. Next/previous wrap around at the ends.
export default function ProductGallery({ photos, title }) {
  const [index, setIndex] = useState(0)
  const count = photos.length
  const photo = photos[index]

  const prev = () => setIndex((i) => (i - 1 + count) % count)
  const next = () => setIndex((i) => (i + 1) % count)

  return (
    <section className="gallery" aria-label="Product photos">
      <div className="gallery__frame">
        <img className="gallery__image" src={photo.src} alt={photo.alt} width="800" height="500" />
      </div>
      <div className="gallery__controls">
        <button type="button" className="icon-button" onClick={prev} aria-label="Previous photo">
          <ArrowLeft />
        </button>
        <button type="button" className="icon-button" onClick={next} aria-label="Next photo">
          <ArrowRight />
        </button>
        <p className="gallery__counter" aria-live="polite">
          <span className="visually-hidden">Photo </span>
          {index + 1} / {count}
        </p>
      </div>
      <span className="visually-hidden">{title}</span>
    </section>
  )
}
