import { useId, useState } from 'react'

// Price with an "i" tooltip. Follows the WAI-ARIA APG tooltip pattern:
// shown on hover or keyboard focus, dismissed with Escape, and the
// tooltip stays open while the pointer is over it (WCAG 1.4.13).
export default function PriceInfo({ price, info }) {
  const [open, setOpen] = useState(false)
  const tipId = useId()

  return (
    <span
      className="price-info"
      onMouseEnter={() => setOpen(true)}
      onMouseLeave={() => setOpen(false)}
      onKeyDown={(e) => {
        if (e.key === 'Escape' && open) {
          e.stopPropagation()
          setOpen(false)
        }
      }}
      onBlur={(e) => {
        if (!e.currentTarget.contains(e.relatedTarget)) setOpen(false)
      }}
    >
      <span className="price-info__price">{price}</span>
      <button
        type="button"
        className="price-info__button"
        aria-describedby={tipId}
        aria-expanded={open}
        onFocus={() => setOpen(true)}
      >
        <span aria-hidden="true">i</span>
        <span className="visually-hidden">Price information</span>
      </button>
      <span id={tipId} role="tooltip" className="price-info__tip" hidden={!open}>
        {info}
      </span>
    </span>
  )
}
