import { useId, useState, useEffect } from 'react'

export const MIN_QTY = 1
export const MAX_QTY = 10

// Quantity input. Typing a valid whole number updates the value immediately;
// the − and + buttons change it by one. Invalid text is flagged and reverted on blur.
export default function QuantityField({ value, onChange }) {
  const id = useId()
  const errId = useId()
  const [text, setText] = useState(String(value))
  const [error, setError] = useState('')

  useEffect(() => {
    setText(String(value))
    setError('')
  }, [value])

  const handleText = (raw) => {
    setText(raw)
    const n = Number(raw)
    if (raw.trim() !== '' && Number.isInteger(n) && n >= MIN_QTY && n <= MAX_QTY) {
      setError('')
      onChange(n)
    } else {
      setError(`Enter a whole number from ${MIN_QTY} to ${MAX_QTY}.`)
    }
  }

  const step = (delta) => {
    const n = Math.min(MAX_QTY, Math.max(MIN_QTY, value + delta))
    onChange(n)
  }

  return (
    <div className="field">
      <label htmlFor={id} className="field__label">Quantity</label>
      <div className="qty">
        <button
          type="button"
          className="qty__button"
          aria-label="Decrease quantity by one"
          onClick={() => step(-1)}
        >
          −
        </button>
        <input
          id={id}
          className="qty__input"
          type="number"
          inputMode="numeric"
          min={MIN_QTY}
          max={MAX_QTY}
          step={1}
          value={text}
          aria-invalid={error ? 'true' : undefined}
          aria-describedby={error ? errId : undefined}
          onChange={(e) => handleText(e.target.value)}
          onBlur={() => {
            setText(String(value))
            setError('')
          }}
        />
        <button
          type="button"
          className="qty__button"
          aria-label="Increase quantity by one"
          onClick={() => step(1)}
        >
          +
        </button>
      </div>
      {error && (
        <p id={errId} className="field__error">
          {error}
        </p>
      )}
    </div>
  )
}
