import { useEffect, useId, useRef, useState } from 'react'
import { ChevronDown } from './Icons.jsx'
import { formatSize } from '../data/trailRunner2.js'

// Size picker following the APG select-only listbox pattern. The list only
// exists while open. Sold-out sizes are announced as unavailable
// (aria-disabled) and cannot be chosen.
export default function SizePicker({
  sizes,
  value,
  onChange,
  invalid,
  errorId,
  guideButtonRef,
  onOpenGuide,
}) {
  const [open, setOpen] = useState(false)
  const labelId = useId()
  const valueId = useId()
  const listId = useId()
  const buttonRef = useRef(null)
  const optionRefs = useRef([])
  const chosen = sizes.find((s) => s.us === value)

  const selectedIndex = sizes.findIndex((s) => s.us === value)

  // When the list opens, move focus into it (on the chosen size, or the first available one).
  useEffect(() => {
    if (!open) return
    const start =
      selectedIndex >= 0 ? selectedIndex : Math.max(0, sizes.findIndex((s) => s.inStock))
    optionRefs.current[start]?.focus()
    // Only run when the list opens, not when the selection changes.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open])

  const close = (returnFocus) => {
    setOpen(false)
    if (returnFocus) buttonRef.current?.focus()
  }

  const choose = (index) => {
    const s = sizes[index]
    if (!s.inStock) return
    onChange(s.us)
    close(true)
  }

  const onOptionKeyDown = (e, index) => {
    const last = sizes.length - 1
    let next = null
    switch (e.key) {
      case 'ArrowDown':
        next = Math.min(last, index + 1)
        break
      case 'ArrowUp':
        next = Math.max(0, index - 1)
        break
      case 'Home':
        next = 0
        break
      case 'End':
        next = last
        break
      case 'Enter':
      case ' ':
        e.preventDefault()
        choose(index)
        return
      case 'Escape':
        e.preventDefault()
        close(true)
        return
      default:
        return
    }
    e.preventDefault()
    optionRefs.current[next]?.focus()
  }

  return (
    <div className="option">
      <div className="option__row">
        <span id={labelId} className="option__label">Size</span>
        <button
          ref={guideButtonRef}
          type="button"
          className="link-button"
          onClick={onOpenGuide}
        >
          Size guide
        </button>
      </div>
      <button
        ref={buttonRef}
        type="button"
        className="option__button"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={listId}
        aria-labelledby={`${labelId} ${valueId}`}
        aria-invalid={invalid ? 'true' : undefined}
        aria-describedby={invalid ? errorId : undefined}
        onClick={() => setOpen((o) => !o)}
      >
        <span id={valueId}>{chosen ? formatSize(chosen) : 'Select a size'}</span>
        <ChevronDown className="option__chevron" />
      </button>

      {open && (
        <ul
          id={listId}
          role="listbox"
          aria-labelledby={labelId}
          className="size-list"
          onBlur={(e) => {
            if (!e.currentTarget.contains(e.relatedTarget) && e.relatedTarget !== buttonRef.current) {
              setOpen(false)
            }
          }}
        >
          {sizes.map((s, i) => {
            const selected = s.us === value
            return (
              <li
                key={s.us}
                ref={(el) => (optionRefs.current[i] = el)}
                role="option"
                aria-selected={selected}
                aria-disabled={!s.inStock || undefined}
                tabIndex={-1}
                className={[
                  'size-list__option',
                  selected ? 'is-selected' : '',
                  s.inStock ? '' : 'is-sold-out',
                ].join(' ')}
                onClick={() => choose(i)}
                onKeyDown={(e) => onOptionKeyDown(e, i)}
              >
                <span className="size-list__us">US {s.us}</span>
                <span className="size-list__eu">EU {s.eu}</span>
                {!s.inStock && <span className="size-list__soldout">Sold out</span>}
              </li>
            )
          })}
        </ul>
      )}
    </div>
  )
}
