import { createPortal } from 'react-dom'
import { useEffect, useId, useRef, useState } from 'react'
import { Close } from './Icons.jsx'
import { sizeChart, SIZE_GUIDE_RANGE, formatSize } from '../data/trailRunner2.js'

const FOCUSABLE = 'button:not([disabled]), input:not([disabled]), [href], [tabindex]:not([tabindex="-1"])'

// Approximate fit: EU ≈ 1.5 × foot length (cm) + 2, US = EU − 33, rounded to a half size.
export function fitFromCm(cm) {
  const eu = cm * 1.5 + 2
  return Math.round((eu - 33) * 2) / 2
}

// Modal dialog (WAI-ARIA APG dialog pattern). Focus is trapped inside,
// Escape closes it, and focus returns to the trigger on close.
export default function SizeGuideDialog({ sizes, onSelect, onClose, returnFocusRef }) {
  const titleId = useId()
  const unitName = useId()
  const cmId = useId()
  const cmHintId = useId()
  const cmErrId = useId()
  const dialogRef = useRef(null)

  const [unit, setUnit] = useState('US')
  const [cmText, setCmText] = useState('')
  const [cmError, setCmError] = useState('')
  const [result, setResult] = useState(null)

  useEffect(() => {
    dialogRef.current?.focus()
    const returnTo = returnFocusRef.current
    return () => returnTo?.focus()
    // Run once on mount/unmount only.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const handleSubmit = (e) => {
    e.preventDefault()
    const cm = Number(cmText)
    if (cmText.trim() === '' || Number.isNaN(cm)) {
      setCmError('Enter your foot length in centimetres.')
      setResult(null)
      return
    }
    if (cm < SIZE_GUIDE_RANGE.minCm || cm > SIZE_GUIDE_RANGE.maxCm) {
      setCmError(`Enter a length between ${SIZE_GUIDE_RANGE.minCm} and ${SIZE_GUIDE_RANGE.maxCm} cm.`)
      setResult(null)
      return
    }
    const us = fitFromCm(cm)
    const min = sizes[0].us
    const max = sizes[sizes.length - 1].us
    if (us < min || us > max) {
      setCmError(`No Trail Runner 2 size fits that length. Sizes run from US ${min} to US ${max}.`)
      setResult(null)
      return
    }
    setCmError('')
    const match = sizes.find((s) => s.us === us)
    setResult(match)
  }

  const handleKeyDown = (e) => {
    if (e.key === 'Escape') {
      e.preventDefault()
      onClose()
      return
    }
    if (e.key !== 'Tab') return
    const items = [...dialogRef.current.querySelectorAll(FOCUSABLE)]
    if (items.length === 0) return
    const first = items[0]
    const last = items[items.length - 1]
    const active = document.activeElement
    if (e.shiftKey && (active === first || active === dialogRef.current)) {
      e.preventDefault()
      last.focus()
    } else if (!e.shiftKey && active === last) {
      e.preventDefault()
      first.focus()
    }
  }

  const sizeLabel = (s) => (unit === 'US' ? `US ${s.us}` : `EU ${s.eu}`)
  const otherLabel = (s) => (unit === 'US' ? `EU ${s.eu}` : `US ${s.us}`)

  return createPortal(
    <div className="dialog-backdrop">
      <div
        ref={dialogRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        className="dialog"
        tabIndex={-1}
        onKeyDown={handleKeyDown}
      >
        <div className="dialog__header">
          <h2 id={titleId} className="dialog__title">Size guide</h2>
          <button type="button" className="icon-button" onClick={onClose} aria-label="Close size guide">
            <Close />
          </button>
        </div>

        <section className="dialog__section" aria-labelledby={`${titleId}-calc`}>
          <h3 id={`${titleId}-calc`} className="dialog__subtitle">Find your size</h3>
          <form onSubmit={handleSubmit} noValidate>
            <fieldset className="radio-row">
              <legend className="field__label">Size system</legend>
              {['US', 'EU'].map((u) => (
                <label key={u} className="radio-label">
                  <input
                    type="radio"
                    name={unitName}
                    value={u}
                    checked={unit === u}
                    onChange={() => setUnit(u)}
                  />
                  {u}
                </label>
              ))}
            </fieldset>

            <div className="field">
              <label htmlFor={cmId} className="field__label">Foot length (cm)</label>
              <p id={cmHintId} className="field__hint">
                Stand on a sheet of paper and measure from your heel to your longest toe.
              </p>
              <input
                id={cmId}
                className="text-input"
                type="number"
                inputMode="decimal"
                step="0.1"
                min={SIZE_GUIDE_RANGE.minCm}
                max={SIZE_GUIDE_RANGE.maxCm}
                value={cmText}
                onChange={(e) => setCmText(e.target.value)}
                aria-invalid={cmError ? 'true' : undefined}
                aria-describedby={cmError ? `${cmHintId} ${cmErrId}` : cmHintId}
              />
              {cmError && (
                <p id={cmErrId} className="field__error">{cmError}</p>
              )}
            </div>

            <button type="submit" className="button button--secondary">Find my size</button>
          </form>

          <div role="status" className="size-result">
            {result && (
              <>
                <p>
                  Your size is <strong>{sizeLabel(result)}</strong> ({otherLabel(result)}).
                </p>
                {result.inStock ? (
                  <button
                    type="button"
                    className="button button--primary"
                    onClick={() => {
                      onSelect(result.us)
                      onClose()
                    }}
                  >
                    Use {formatSize(result)} and close
                  </button>
                ) : (
                  <p className="field__error">{formatSize(result)} is sold out right now.</p>
                )}
              </>
            )}
          </div>
        </section>

        <section className="dialog__section" aria-labelledby={`${titleId}-chart`}>
          <h3 id={`${titleId}-chart`} className="dialog__subtitle">Size chart</h3>
          <table className="size-chart">
            <caption className="visually-hidden">Trail Runner 2 size chart</caption>
            <thead>
              <tr>
                <th scope="col">US</th>
                <th scope="col">EU</th>
                <th scope="col">UK</th>
                <th scope="col">Foot length (cm)</th>
              </tr>
            </thead>
            <tbody>
              {sizeChart.map((row) => (
                <tr key={row.us}>
                  <td>{row.us}</td>
                  <td>{row.eu}</td>
                  <td>{row.uk}</td>
                  <td>{row.cm}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </section>
      </div>
    </div>,
    document.body,
  )
}
