import { useId, useRef, useState } from 'react'
import { details, reviews, shipping, product } from '../data/trailRunner2.js'
import { Star } from './Icons.jsx'

// Tabs (WAI-ARIA APG tabs pattern): one panel visible at a time, arrow keys / Home / End move between tabs.
const TABS = [
  { id: 'details', label: 'Details' },
  { id: 'reviews', label: 'Reviews' },
  { id: 'shipping', label: 'Shipping' },
]

export default function MoreInformation() {
  const base = useId()
  const [selected, setSelected] = useState('details')
  const tabRefs = useRef({})

  const select = (id, focus = false) => {
    setSelected(id)
    if (focus) tabRefs.current[id]?.focus()
  }

  const onKeyDown = (e, index) => {
    const n = TABS.length
    let next
    if (e.key === 'ArrowRight') next = (index + 1) % n
    else if (e.key === 'ArrowLeft') next = (index - 1 + n) % n
    else if (e.key === 'Home') next = 0
    else if (e.key === 'End') next = n - 1
    else return
    e.preventDefault()
    select(TABS[next].id, true)
  }

  return (
    <section className="more-info" aria-labelledby={`${base}-heading`}>
      <h2 id={`${base}-heading`} className="section-title">More information</h2>
      <div role="tablist" aria-label="Product information" className="tablist">
