import { useId, useState } from 'react'
import { faqs } from '../data/trailRunner2.js'
import { ChevronDown } from './Icons.jsx'

// Accordion (WAI-ARIA APG accordion pattern): each heading contains a button
// that shows or hides its answer. Answers are hidden until opened.
export default function FaqAccordion() {
  const base = useId()
  const [openIds, setOpenIds] = useState([])

  const toggle = (id) =>
    setOpenIds((ids) => (ids.includes(id) ? ids.filter((x) => x !== id) : [...ids, id]))

  return (
    <section className="faq" aria-labelledby={`${base}-heading`}>
      <h2 id={`${base}-heading`} className="section-title">Questions</h2>
      {faqs.map((f) => {
        const expanded = openIds.includes(f.id)
        return (
          <div key={f.id} className="faq__item">
            <h3 className="faq__heading">
              <button
                type="button"
                className="faq__button"
                aria-expanded={expanded}
                aria-controls={`${base}-${f.id}`}
                id={`${base}-${f.id}-button`}
                onClick={() => toggle(f.id)}
              >
                <span>{f.question}</span>
                <ChevronDown className={expanded ? 'faq__chevron is-open' : 'faq__chevron'} />
              </button>
            </h3>
            <div
              id={`${base}-${f.id}`}
              role="region"
              aria-labelledby={`${base}-${f.id}-button`}
              hidden={!expanded}
              className="faq__answer"
            >
              <p>{f.answer}</p>
            </div>
          </div>
        )
      })}
    </section>
  )
}
