import { useId, useRef, useState } from 'react'
import { ChevronDown } from './Icons.jsx'

// Shows only the chosen colour. Activating the button opens a radio group of
// round swatches. Choosing one (click, Space or Enter) closes the list and
// returns focus to the button; Escape or leaving the list also closes it.
export default function ColorPicker({ colors, value, onChange }) {
  const [open, setOpen] = useState(false)
  const labelId = useId()
  const valueId = useId()
  const panelId = useId()
  const groupName = useId()
  const buttonRef = useRef(null)
  const current = colors.find((c) => c.id === value)

  const close = (returnFocus) => {
    setOpen(false)
    if (returnFocus) buttonRef.current?.focus()
  }

  return (
    <div className="option">
      <span id={labelId} className="option__label">Color</span>
      <button
        ref={buttonRef}
        type="button"
        className="option__button"
        aria-expanded={open}
        aria-controls={panelId}
        aria-labelledby={`${labelId} ${valueId}`}
        onClick={() => setOpen((o) => !o)}
      >
        <span className="swatch" style={{ background: current.swatch }} aria-hidden="true" />
        <span id={valueId}>{current.name}</span>
        <ChevronDown className="option__chevron" />
      </button>

      {open && (
        <fieldset
          id={panelId}
          className="swatch-list"
          onKeyDown={(e) => {
            if (e.key === 'Escape') {
              e.preventDefault()
              close(true)
            }
          }}
          onBlur={(e) => {
            if (!e.currentTarget.contains(e.relatedTarget) && e.relatedTarget !== buttonRef.current) {
              setOpen(false)
            }
          }}
        >
          <legend className="visually-hidden">Choose a color</legend>
          {colors.map((c) => (
            <label key={c.id} className="swatch-option">
              <input
                type="radio"
                name={groupName}
                value={c.id}
                checked={c.id === value}
                onChange={() => onChange(c.id)}
                onClick={() => close(true)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') close(true)
                }}
              />
              <span className="swatch" style={{ background: c.swatch }} aria-hidden="true" />
              <span>{c.name}</span>
            </label>
          ))}
        </fieldset>
      )}
    </div>
  )
}
