import { useEffect, useId, useRef, useState } from 'react'
import SiteHeader from '../components/SiteHeader.jsx'
import Breadcrumb from '../components/Breadcrumb.jsx'
import ProductGallery from '../components/ProductGallery.jsx'
import PriceInfo from '../components/PriceInfo.jsx'
import ColorPicker from '../components/ColorPicker.jsx'
import SizePicker from '../components/SizePicker.jsx'
import SizeGuideDialog from '../components/SizeGuideDialog.jsx'
import QuantityField from '../components/QuantityField.jsx'
import MoreInformation from '../components/MoreInformation.jsx'
import FaqAccordion from '../components/FaqAccordion.jsx'
import SiteFooter from '../components/SiteFooter.jsx'
import { Heart, Star } from '../components/Icons.jsx'
import {
  product,
  colors,
  sizes,
  breadcrumb,
  photosFor,
  formatPrice,
  formatSize,
} from '../data/trailRunner2.js'

export default function ProductPage() {
  const [colorId, setColorId] = useState(colors[0].id)
  const [sizeUs, setSizeUs] = useState(null)
  const [quantity, setQuantity] = useState(1)
  const [wishlisted, setWishlisted] = useState(false)
  const [cartCount, setCartCount] = useState(0)
  const [sizeError, setSizeError] = useState(false)
  const [cartMessage, setCartMessage] = useState('')
  const [wishMessage, setWishMessage] = useState('')
  const [guideOpen, setGuideOpen] = useState(false)

  const sizeButtonRef = useRef(null)
  const guideButtonRef = useRef(null)
  const sizeErrorId = useId()

  const color = colors.find((c) => c.id === colorId)
  const size = sizes.find((s) => s.us === sizeUs)
  const photos = photosFor(colorId)
  const price = formatPrice(product.price, product.currency)

  useEffect(() => {
    document.title = `${product.name} | Stride`
  }, [])

  const addToCart = () => {
    if (!size) {
      setSizeError(true)
      setCartMessage('')
      sizeButtonRef.current?.focus()
      return
    }
    setSizeError(false)
    setCartCount((n) => n + quantity)
    setCartMessage(
      `Added ${quantity} ${quantity === 1 ? 'pair' : 'pairs'} of ${product.name} in ${color.name.toLowerCase()}, ${formatSize(size)}, to your cart.`,
    )
  }

  const toggleWishlist = () => {
    const next = !wishlisted
    setWishlisted(next)
    setWishMessage(next ? `${product.name} saved to your wishlist.` : `${product.name} removed from your wishlist.`)
  }

  return (
    <div className="page" inert={guideOpen}>
      <a className="skip-link" href="#product-main">Skip to product</a>
      <SiteHeader cartCount={cartCount} />

      <main id="product-main" className="product-main">
        <Breadcrumb items={breadcrumb} />

        <div className="product">
          <ProductGallery key={colorId} photos={photos} />

          <div className="product__info">
            <h1 className="product__title">{product.name}</h1>
            <p className="product__tagline">{product.tagline}</p>
            <p className="rating">
              <Star className="rating__star" />
              <span>
                Rated {product.rating.toFixed(1)} out of 5 ({product.reviewCount} reviews)
              </span>
            </p>

            <p className="price">
              <PriceInfo
                price={price}
                info="Includes all applicable taxes."
              />
            </p>

            <p className="product__description">{product.description}</p>

            <div className="options">
              <ColorPicker colors={colors} value={colorId} onChange={setColorId} />

              <SizePicker
                sizes={sizes}
                value={sizeUs}
                onChange={(us) => {
                  setSizeUs(us)
                  setSizeError(false)
                }}
                invalid={sizeError}
                errorId={sizeErrorId}
                guideButtonRef={guideButtonRef}
                onOpenGuide={() => setGuideOpen(true)}
                buttonRef={sizeButtonRef}
              />
              {sizeError && (
                <p id={sizeErrorId} className="field__error">
                  Select a size before adding this shoe to your cart.
                </p>
              )}

              <QuantityField value={quantity} onChange={setQuantity} />
            </div>

            <div className="actions">
              <button type="button" className="button button--primary" onClick={addToCart}>
                Add to cart
              </button>
              <button
                type="button"
                className="button button--secondary"
                aria-pressed={wishlisted}
                onClick={toggleWishlist}
              >
                <Heart className="button__icon" filled={wishlisted} />
                Save to wishlist
              </button>
            </div>

            <div role="status" className="status">
              {cartMessage && <p>{cartMessage}</p>}
              {wishMessage && <p className="status__secondary">{wishMessage}</p>}
            </div>
          </div>
        </div>

        <MoreInformation />
        <FaqAccordion />
      </main>

      <SiteFooter />

      {guideOpen && (
        <SizeGuideDialog
          sizes={sizes}
          returnFocusRef={guideButtonRef}
          onSelect={(us) => {
            setSizeUs(us)
            setSizeError(false)
          }}
          onClose={() => setGuideOpen(false)}
        />
      )}
    </div>
  )
}
