  color: var(--muted);
}

.size-list__soldout {
  font-size: 0.75rem;
  color: var(--muted);
  text-decoration: none;
  display: inline-block;
}

.field__error {
  color: var(--danger);
  font-weight: 600;
  margin-top: 6px;
  font-size: 0.95rem;
}

.field__hint {
  color: var(--muted);
  font-size: 0.9rem;
  margin-bottom: 6px;
}

.field {
  display: grid;
  gap: 0;
}

.qty {
  display: inline-flex;
  align-items: stretch;
  border: 1px solid var(--line);
  border-radius: 6px;
  width: fit-content;
  overflow: hidden;
}

.qty__button {
  width: 48px;
  min-height: 48px;
  border: 0;
  background: var(--paper);
  font: inherit;
  font-size: 1.25rem;
  cursor: pointer;
}

.qty__button:hover {
  background: var(--panel);
}

.qty__input {
  width: 64px;
  min-height: 48px;
  border: 0;
  border-inline: 1px solid var(--line);
  text-align: center;
  font: inherit;
  font-size: 1.05rem;
  -moz-appearance: textfield;
}

.qty__input::-webkit-outer-spin-button,
.qty__input::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

.text-input {
  min-height: 44px;
  padding: 8px 12px;
  border: 1px solid var(--line);
  border-radius: 6px;
  font: inherit;
  width: 100%;
  max-width: 220px;
}

.text-input[aria-invalid='true'] {
  border: 2px solid var(--danger);
}

.radio-row {
  border: 0;
  padding: 0;
  margin: 0 0 16px;
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: center;
}

.radio-row legend {
  padding: 0;
  margin-bottom: 6px;
  width: 100%;
}

.radio-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 44px;
  padding: 0 8px;
  cursor: pointer;
}

.radio-label input {
  width: 20px;
  height: 20px;
  margin: 0;
  accent-color: var(--brand);
}

/* ---------- Buttons ---------- */
.actions {
  margin-top: 24px;
  display: grid;
  gap: 12px;
}

.button {
  min-height: 52px;
  padding: 12px 20px;
  border-radius: 999px;
  font: inherit;
  font-weight: 700;
  font-size: 1rem;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 2px solid transparent;
}

.button--primary {
  background: var(--brand);
  color: #fff;
}

.button--primary:hover {
  background: var(--brand-dark);
}

.button--secondary {
  background: var(--paper);
  color: var(--ink);
  border-color: var(--ink);
}

.button--secondary:hover {
  background: var(--panel);
}

.button--secondary[aria-pressed='true'] {
  background: var(--ink);
  color: #fff;
}

.button__icon {
  flex: none;
}

.status {
  margin-top: 16px;
  min-height: 1.5em;
}

.status p {
  padding: 12px 14px;
  border-left: 4px solid #1e7a3c;
  background: #eaf6ee;
  color: var(--ink);
}

.status__secondary {
  margin-top: 8px;
  font-size: 0.95rem;
}

.status:empty,
.status:has(> :not(.status__secondary):not(p)):empty {
  min-height: 0;
}

.status:not(:has(p)) {
  min-height: 0;
}

.status .status__secondary:not(:first-child) {
  background: transparent;
  border: 0;
  padding: 0;
  color: var(--muted);
}

/* ---------- More information (tabs) ---------- */
.more-info {
  margin-top: 56px;
  border-top: 1px solid #d5d9de;
  padding-top: 32px;
}

.section-title {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 16px;
}

.tablist {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  border-bottom: 1px solid #c5cad1;
}

.tab {
  min-height: 48px;
  padding: 10px 18px;
  border: 0;
  border-bottom: 3px solid transparent;
  background: none;
  font: inherit;
  font-weight: 600;
  color: var(--muted);
  cursor: pointer;
  margin-bottom: -1px;
}

.tab[aria-selected='true'] {
  color: var(--ink);
  border-bottom-color: var(--ink);
}

.tabpanel {
  padding: 20px 4px;
  max-width: 72ch;
}

.bullets {
  padding-left: 20px;
  display: grid;
  gap: 8px;
}

.rating-summary {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 16px;
}

.reviews {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  gap: 16px;
}

.review {
  padding-bottom: 16px;
  border-bottom: 1px solid #e0e3e7;
}

.review__meta {
  color: var(--muted);
  font-size: 0.9rem;
  margin-bottom: 4px;
}

/* ---------- FAQ (accordion) ---------- */
.faq {
  margin-top: 48px;
  border-top: 1px solid #d5d9de;
  padding-top: 32px;
  max-width: 800px;
}

.faq__item {
  border-bottom: 1px solid #c5cad1;
}

.faq__heading {
  font-size: 1.05rem;
}

.faq__button {
  width: 100%;
  min-height: 52px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  padding: 12px 4px;
  border: 0;
  background: none;
  font: inherit;
  font-weight: 600;
  color: var(--ink);
  text-align: left;
  cursor: pointer;
}

.faq__chevron {
  flex: none;
  transition: transform 0.15s ease;
}

.faq__chevron.is-open {
  transform: rotate(180deg);
}

.faq__answer {
  padding: 0 4px 16px;
  color: var(--muted);
  max-width: 68ch;
}

/* ---------- Size guide dialog ---------- */
.dialog-backdrop {
  position: fixed;
  inset: 0;
  z-index: 50;
  background: rgba(0, 0, 0, 0.55);
  display: grid;
  place-items: center;
  padding: 16px;
}

.dialog {
  width: min(680px, 100%);
  max-height: calc(100vh - 32px);
  overflow-y: auto;
  background: var(--paper);
  border-radius: 10px;
  padding: 24px;
  box-shadow: 0 16px 48px rgba(0, 0, 0, 0.3);
}

.dialog:focus {
  outline: none;
}

.dialog__header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
}

.dialog__title {
  font-size: 1.5rem;
  font-weight: 700;
}

.dialog__section {
  padding: 16px 0;
  border-top: 1px solid #e0e3e7;
}

.dialog__subtitle {
  font-size: 1.1rem;
  font-weight: 700;
  margin-bottom: 12px;
}

.dialog__section form {
  display: grid;
  gap: 8px;
}

.dialog__section .button {
  justify-self: start;
}

.size-result {
  margin-top: 12px;
  display: grid;
  gap: 10px;
  justify-items: start;
}

.size-chart {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.95rem;
}

.size-chart th,
.size-chart td {
  padding: 8px 10px;
  text-align: left;
  border-bottom: 1px solid #e0e3e7;
}

.size-chart th {
  font-weight: 700;
}

/* ---------- Footer ---------- */
.site-footer {
  background: var(--panel);
  border-top: 1px solid #d5d9de;
  padding: 40px 20px 24px;
}

.site-footer__inner {
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  gap: 32px;
}

@media (min-width: 700px) {
  .site-footer__inner {
    grid-template-columns: repeat(3, 1fr);
  }
}

.site-footer h2 {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 12px;
}

.site-footer ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 4px;
}

.site-footer li a {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 32px;
  padding: 4px 0;
}

.site-footer__legal {
  max-width: 1280px;
  margin: 32px auto 0;
  color: var(--muted);
  font-size: 0.9rem;
}

/* ---------- Small screens ---------- */
@media (max-width: 480px) {
  .product__title {
    font-size: 1.6rem;
  }
  .gallery__controls {
    flex-wrap: wrap;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
  }
}
