import { useId, useState } from 'react'

export const MIN_QTY = 1
export const MAX_QTY = 10

// Quantity input. Typing a valid whole number updates the value immediately;
// the − and + buttons change it by one. While the user is typing we keep a
// draft string; otherwise the input always shows the current value.
// Invalid text is flagged and reverted on blur.
export default function QuantityField({ value, onChange }) {
  const id = useId()
  const errId = useId()
  const [draft, setDraft] = useState(null)
  const [error, setError] = useState('')

  const displayed = draft ?? String(value)

  const handleText = (raw) => {
    setDraft(raw)
    const n = Number(raw)
    if (raw.trim() !== '' && Number.isInteger(n) && n >= MIN_QTY && n <= MAX_QTY) {
      setError('')
      onChange(n)
    } else {
      setError(`Enter a whole number from ${MIN_QTY} to ${MAX_QTY}.`)
    }
  }

  const step = (delta) => {
    setDraft(null)
    setError('')
    onChange(Math.min(MAX_QTY, Math.max(MIN_QTY, value + delta)))
  }

  return (
    <div className="field">
      <label htmlFor={id} className="field__label">Quantity</label>
      <div className="qty">
        <button
          type="button"
          className="qty__button"
          aria-label="Decrease quantity by one"
          onClick={() => step(-1)}
        >
          −
        </button>
        <input
          id={id}
          className="qty__input"
          type="number"
          inputMode="numeric"
          min={MIN_QTY}
          max={MAX_QTY}
          step={1}
          value={displayed}
          aria-invalid={error ? 'true' : undefined}
          aria-describedby={error ? errId : undefined}
          onChange={(e) => handleText(e.target.value)}
          onBlur={() => {
            setDraft(null)
            setError('')
          }}
        />
        <button
          type="button"
          className="qty__button"
          aria-label="Increase quantity by one"
          onClick={() => step(1)}
        >
          +
        </button>
      </div>
      {error && (
        <p id={errId} className="field__error">
          {error}
        </p>
      )}
    </div>
  )
}
EOF
